def _emit_claim_payload(
    claims: ClaimCollection,
    claim_id: str,
    payload,
    *,
    kind: str,
    subject: str,
    data=None,
):
    return claims.claim(claim_id, payload, kind=kind, subject=subject, data=data)


def diff_rows(*, claims: ClaimCollection):
    return _emit_claim_payload(
        claims,
        "mp.plus.diff-from-plain",
        _DIFF_ROWS,
        kind="enum",
        subject="mp:plus",
    )


def _json_tmpl_plain_compare(*, claims: ClaimCollection):
    return _emit_claim_payload(
        claims,
        "mp.plain.template.stmpl-format-example",
        _JSON_TMPL_PLAIN_COMPARE,
        kind="format",
        subject="mp:plain",
        data={"stmpl": "קו״כ|את|אַ֠תָּ֠ה"},
    )


def gen_html_file(tdm_ch, claims: ClaimCollection):
    """Generate mpplus_diff_from_plain.html in the given output directory."""
    cbody = build_body(claims=claims)
    return author.help_gen_html_file(
        __file__, tdm_ch, DIFF_FROM_PLAIN_DOC, _TITLE, cbody
    )


def build_body(*, claims: ClaimCollection):
    back_link = author.anchor_h("Reading $MAM-parsed-plus", _PLUS_DOC)
    return [
        author.heading_level_1(_TITLE),
        author.para(["← Back to ", back_link]),
        author.para(
            [
                "This table stays concise so the main format differences are quick to scan.",
                " Header metadata is intentionally aligned between plain and plus now",
                " (a simplification that fits current one-file-per-book24 outputs),",
                " so header-shape differences are not listed here.",
                " The exhaustive list of templates removed from plus is on ",
                author.anchor_h("Plain-only Templates", PLAIN_ONLY_TEMPLATES_DOC),
                ".",
            ]
        ),
        author.std_table(
            diff_rows(claims=claims), arg_to_troh=["Feature", "Plain", "Plus"]
        ),
        author.para(
            [
                "Template names use Hebrew gershayim ",
                mb_html.code("״"),
                " (for example ",
                author.hbo("כו״ק"),
                "), not ASCII double quote ",
                mb_html.code('"'),
                ".",
            ]
        ),
        author.para(
            [
                "Example of the stringified template format ",
                mb_html.code('{"stmpl": "..."}'),
                " (present in plain, replaced in plus):",
            ]
        ),
        json_block.json_block_raw_html(_json_tmpl_plain_compare(claims=claims)),
    ]


def _build_body(*, claims: ClaimCollection):
    return build_body(claims=claims)
